QuadContainerStatistics::QuadContainerStatistics(
    QuadContainerAdaptor c)
    : ScoreState(c->get_model(), c->get_name() + " statistics") {
  container_ = c;
  total_ = 0;
  max_ = 0;
  min_ = std::numeric_limits<unsigned int>::max();
  checks_ = 0;
  track_unique_ = false;
}

void QuadContainerStatistics::set_track_unique(bool tf) {
  track_unique_ = tf;
  unique_.clear();
}
void QuadContainerStatistics::show_statistics(std::ostream &out) const {
  out << "Average: " << static_cast<double>(total_) / checks_ << std::endl;
  out << "Min, Max: " << min_ << ", " << max_ << std::endl;
  if (track_unique_) {
    out << "Number unique: " << unique_.size() << std::endl;
  }
}

void QuadContainerStatistics::do_before_evaluate() {
  unsigned int n = container_->get_number();
  total_ += n;
  ++checks_;
  max_ = std::max(max_, n);
  min_ = std::min(min_, n);
  if (track_unique_) {
    for (unsigned int i = 0; i < container_->get_number(); ++i) {
      unique_.insert(container_->get(i));
    }
  }
}

