void DistributeQuadsScoreState::update_lists_if_necessary() const {
  std::size_t h = input_->get_contents_hash();
  if (h == input_version_) return;
  input_version_ = h;

  Vector<ParticleIndexQuads> output(data_.size());
  for(ParticleIndexQuad it : input_->get_contents()) {
    for (unsigned int i = 0; i < data_.size(); ++i) {
      if (data_[i].get<1>()->get_value_index(get_model(), it) ==
          data_[i].get<2>()) {
        output[i].push_back(it);
      }
    }
  }
  for (unsigned int i = 0; i < output.size(); ++i) {
    data_[i].get<0>()->set(output[i]);
  }
}

