EventQuadsOptimizerState::EventQuadsOptimizerState(
    QuadPredicate *pred, QuadContainerAdaptor container, int value,
    int min_count, int max_count, std::string name)
    : OptimizerState(container->get_model(), name),
      pred_(pred),
      container_(container),
      v_(value),
      min_(min_count),
      max_(max_count) {}

void EventQuadsOptimizerState::do_update(unsigned int) {
  int met = 0;
  Model *m = get_optimizer()->get_model();
  for(ParticleIndexQuad it : container_->get_contents()) {
    if (pred_->get_value_index(m, it) == v_) ++met;
  }
  if (met >= min_ && met < max_) {
    throw IMP::EventException("an event occurred");
  }
}
